  assert.deepEqual(r.totals, { region: 'Total', n: 6, total: 607, reps: 4, avg: 121.4 });
  const nov = run(sales, { filters: [{ field: 'month', eq: '2026-11' }, { field: 'amount', gte: 50 }], groupBy: ['rep'], measures: [{ name: 'max', op: 'max', field: 'amount' }] });
